var ENT=[["GraphQL", "Client-shaped data queries."], ["Nginx", "High-performance reverse proxy."], ["Redis", "Caching and real-time state."], ["PostgreSQL", "The serious backend database."], ["Express", "The minimal, unopinionated Node.js web framework everything else learned from."], ["FastAPI", "Python's modern async API framework with automatic OpenAPI docs from type hints."], ["Django", "Batteries-included Python framework with ORM, auth and admin out of the box."]];
var TECH=[["REST resource design", "Nouns as URLs, verbs as HTTP methods, status codes as the contract."], ["JWT sessions", "Signed stateless tokens carrying identity between services."], ["Rate limiting", "Token buckets and sliding windows protecting APIs from abuse."], ["Request validation", "Schema-checking every input at the boundary before business logic."], ["Database migrations", "Evolving production schemas without downtime or data loss."], ["Background jobs", "Queues and workers for slow work outside the request cycle."], ["Health checks", "Liveness and readiness endpoints orchestrators poll."], ["Structured logging", "JSON logs with correlation IDs tracing requests end to end."], ["API versioning", "Evolving contracts without breaking existing clients."], ["Load testing", "Proving the stack holds under expected traffic before launch."]];
