function demoProg(rnd,title,topic){
  var lines=[];
  lines.push('// JAH demo program - run with: node demo.js');
  lines.push('// Demo: '+title);
  lines.push('(function(){"use strict";');
  lines.push('var topic='+jsq(topic)+';');
  var mode=(rnd()*3)|0, i;
  if(mode===0){
    lines.push('var steps=["charter","execute","verify","deliver"];');
    lines.push('console.log("Trace: "+topic);');
    lines.push('for(var i=0;i<steps.length;i++){console.log(" step "+(i+1)+": "+steps[i]+" ["+topic+"]");}');
    lines.push('console.log("OK - trace complete");');
  }else if(mode===1){
    lines.push('var vals=[],i;for(i=0;i<6;i++){vals.push((i*37+11)%97);}');
    lines.push('var sum=0;for(i=0;i<vals.length;i++){sum+=vals[i];}');
    lines.push('console.log("Data: "+topic+" -> ["+vals.join(", ")+"]");');
    lines.push('console.log("sum="+sum+" mean="+(sum/vals.length).toFixed(2));');
  }else{
    lines.push('var checks=[["inputs declared",true],["outputs verified",true],["deterministic",true]];');
    lines.push('var pass=0,i;for(i=0;i<checks.length;i++){console.log((checks[i][1]?"PASS ":"FAIL ")+checks[i][0]+" ["+topic+"]");if(checks[i][1]){pass++;}}');
    lines.push('console.log(pass+"/"+checks.length+" checks passed");');
  }
  lines.push('})();');
  return lines.join("\n");
}
function genVariant(rnd,seed){
  var roll=rnd(), topic, group, title, definition, src, ladder;
  if(roll<0.30){
    var e=pick(ENT,rnd); topic=e[0];
    group=KIND; title=e[0]+' - boundless '+KIND+' record';
    definition=e[1]; src='signature-line'; ladder=2;
  }else if(roll<0.60){
    var t=pick(TECH,rnd); topic=t[0];
    group='techniques'; title=t[0]+' - boundless technique record';
    definition=t[1]; src='Public knowledge - standard computing reference'; ladder=2;
  }else if(roll<0.80){
    var s=pick(STDN,rnd); topic=s;
    group='standards'; title=s+' - boundless standard record';
    definition='Boundless elaboration of the '+s+' standard as it applies to this build capability.';
    src='Public knowledge - standard computing reference'; ladder=2;
  }else{
    topic='drill-'+seed;
    group='drills'; title='Boundless drill '+seed+' - applied practice';
    definition='A generated drill exercising this database\'s capability on seed-derived data.';
    src='signature-line'; ladder=1+((rnd()*3)|0);
  }
  var desc=topic+': '+definition+' '+pick(APPS,rnd)+' Seed '+seed+' reproduces this record exactly - deterministic generation means the same seed always yields this same record, and every claim above is checkable against the archive schema.';
  return {
    id: PREFIX+String(seed).padStart(6,'0'),
    t: title, title: title,
    definition: definition,
    description: desc,
    program: demoProg(rnd,title,topic),
    language: 'javascript',
    g: group, group: group, ladder: ladder, c: 1,
    source: src, last_verified: "2026-10-19",
    edition: "public"
  };
}
function generate(seed,opts,rnd){
  opts=opts||{}; rnd=rnd||prng(seed);
  if(seed>=1&&seed<=ARCHIVE.length){return JSON.parse(JSON.stringify(ARCHIVE[seed-1]));}
  var rec=genVariant(rnd,seed);
  var g=opts.group||opts.category;
  if(g&&FIELDS.indexOf(g)>=0){rec.group=g;rec.g=g;}
  return rec;
}
function validate(r){
  var e=[];
  if(!r||typeof r!=='object')return {ok:false,errors:['not an object']};
  if(!new RegExp('^'+PREFIX.replace(/-/g,'\\-')+'\\d{6}$').test(r.id||''))e.push('id');
  if(typeof r.title!=='string'||!r.title.length)e.push('title');
  if(typeof r.description!=='string'||r.description.length<200)e.push('description');
  if(typeof r.program!=='string'||r.program.indexOf('console.log')<0)e.push('program');
  if(FIELDS.indexOf(r.group)<0)e.push('group');
  if(!(r.ladder>=1&&r.ladder<=3))e.push('ladder');
  if(typeof r.source!=='string'||!r.source.length)e.push('source');
  return {ok:!e.length,errors:e};
}
function driftCheck(rec,sample){
  var seen={};(sample||[]).forEach(function(s){if(s&&(s.t||s.title))seen[s.t||s.title]=1;});
  if(rec&&seen[rec.title||rec.t])return {ok:false,errors:['duplicate title in archive sample']};
  return {ok:true,errors:[]};
}
